    @Test fun legacySchemasTwoThroughEighteenReadWithoutInventingNewInputs() {
        for(version in 2..18) {
            val o=JSONObject(encodeData(AppData())).put("version",version)
            listOf("foreignTaxRelief","foreignMonthlyOtherTax","foreignAnnualVerifiedTax").forEach{o.getJSONObject("settings").remove(it)}
            val s=decodeData(o.toString()).settings
            assertNull(s.foreignTaxRelief);assertNull(s.foreignMonthlyOtherTax);assertNull(s.foreignAnnualVerifiedTax)
        }
    }
    @Test fun futureSchemaCannotSilentlyDropNewFinancialData() {
        assertTrue(runCatching { decodeData(JSONObject(encodeData(AppData())).put("version",DATA_VERSION+1).toString()) }.isFailure)
    }
    @Test fun cleanInstallHasNoNewPersonalFinancialDefaultsOrRecords() {
        val d=AppData();assertTrue(d.shifts.isEmpty());assertNull(d.active);assertFalse(d.setupComplete)
        assertNull(d.settings.foreignTaxRelief);assertNull(d.settings.foreignMonthlyOtherTax)
        assertNull(d.settings.foreignAnnualVerifiedTax);assertNull(d.settings.annualEmploymentGross)
    }
    @Test fun invalidNewFieldsFailRealSettingsDecodeValidation() {
        for(key in listOf("foreignTaxRelief","foreignMonthlyOtherTax","foreignAnnualVerifiedTax")) {
            for(v in listOf(-1.0,1_000_000_000_001.0)) {
                val j=JSONObject(encodeData(AppData()));j.getJSONObject("settings").put(key,v)
                assertTrue("$key=$v",runCatching { decodeData(j.toString()) }.isFailure)
            }
        }
    }
    @Test fun missingNewCountryInputsAfterOldBackupStayUnavailableRatherThanGuessing() {
        val s=annual("IT").copy(foreignTaxRelief=null,foreignMonthlyOtherTax=null)
        assertNull(n(decodeData(encodeData(AppData(settings=s))).settings))
    }
}
